export function readConfig(text: string): Record<string, unknown> {
  try {
    return JSON.parse(text);
  } catch (err) {
    console.error('invalid config', err);
    throw new Error('config is not valid JSON');
  }
}

export function readName(text: string): string {
  return String(readConfig(text).name ?? 'unnamed');
}

